245	\begin{lemma}[Consistency versus closeness; Facts 4.13 and 4.14 in \cite{Natarajan2018NEEXP}]\label{fact:agreement}
246		\lean{MIPStarRE.QPBT.opFamilyDistSq_le_two_mul_consistencyDefect, MIPStarRE.QPBT.consistencyDefect_le_opFamilyDistSq_of_projective, MIPStarRE.QPBT.consistencyDefect_le_sqrt_of_projective_left}
247		\uses{def:consistency, def:povm-distance}
248		For POVMs $\{A^x_a\}$ and $\{B^x_a\}$, the following hold.
249		\begin{enumerate}
250			\item If $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$, then $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$.
251			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ \emph{and} $\{A^x_a\}$ and $\{B^x_a\}$ are projective measurements, then $A^x_a \ot \Id_B \simeq_\delta \Id_A \ot B^x_a$.
252			\item If $A^x_a \ot \Id_B \approx_\delta \Id_A \ot B^x_a$ and either $\{A^x_a\}$ or $\{B^x_a\}$ is a projective measurement, then $A^x_a \ot \Id_B \simeq_{\delta^{1/2}} \Id_A \ot B^x_a$.
253		\end{enumerate}
254	\end{lemma}
255	\begin{proof}
256		Stated in the source without proof; these are Facts 4.13 and 4.14 of \cite{Natarajan2018NEEXP}. For the first item, expand each term $\lVert (A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi} \rVert^2$ and use $ (A^x_a)^2 \le A^x_a$, $(B^x_a)^2 \le B^x_a$ together with completeness of the two POVMs: summing over $a$ and averaging over $x$ bounds the total by at most twice the off-diagonal mass, which is $O(\delta)$ by hypothesis. When both families are projective the two operator inequalities hold with equality, so the expansion equals exactly twice the off-diagonal mass; reading this identity in the other direction gives the second item. For the third item, write the off-diagonal mass $\sum_{a \ne b} \bra{\psi} A^x_a \ot B^x_b \ket{\psi}$ as an inner product involving $(A^x_a \ot \Id - \Id \ot B^x_a)\ket{\psi}$, using projectivity of one of the two families, and apply the Cauchy--Schwarz inequality; this route costs a square root in the error.
257	\end{proof}
